 c=['Tespit raporunun gümrük idaresine sunulduğu tarihten itibaren on iki ay', 'Üçüncü aykırılığın idarece tespit edildiği tarihten itibaren altı ay', 'Üçüncü aykırılığın idarece tespit edildiği tarihten itibaren on iki ay', 'İçinde bulunulan takvim yılının sonuna kadar'],
 tuzak=False,
